// \"tetap\", \"bertambah_baru\", \"perbaikan\", \"afkir\"\n\n  keterangan String?\n\n  komunitasId String?\n  komunitas   Komunitas? @relation(fields: [komunitasId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  peminjaman PeminjamanAset[]\n}\n\n// Sub-model: Catatan Peminjaman Aset oleh Warga\nmodel PeminjamanAset {\n  id           String         @id @default(uuid())\n  inventarisId String\n  inventaris   InventarisAset @relation(fields: [inventarisId], references: [id], onDelete: Cascade)\n\n  namaPeminjam   String\n  noRumah        String?\n  kontakPeminjam String?\n  jumlahPinjam   Int     @default(1)\n  keperluan      String // Hajatan, tasyakuran, kematian\n\n  tanggalPinjam  DateTime  @default(now())\n  tanggalKembali DateTime?\n  status         String    @default(\"dipinjam\") // \"dipinjam\" | \"dikembalikan\"\n  catatanKondisi String?\n\n  createdAt DateTime @default(now())\n}\n\n// 4. Refleksi Tahunan: Kendala, Solusi, & Rencana Masa Depan\nmodel EvaluasiTahunan {\n  id    String @id @default(uuid())\n  tahun Int\n\n  kataPengantar    String? // Pesan pembuka dari Ketua RT\n  kendalaTantangan String // Hambatan operasional selama setahun\n  solusiTindakan   String // Solusi dan rekomendasi yang diterapkan\n  usulanRencana    String // Rencana kerja prioritas tahun berikutnya\n  estimasiAnggaran Int     @default(0)\n\n  komunitasId String?\n  komunitas   Komunitas? @relation(fields: [komunitasId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([komunitasId, tahun])\n}\n\n// 5. Modul Arisan Warga & Pengocokan Roda Putar\nmodel KelompokArisan {\n  id                String   @id @default(uuid())\n  nama              String // e.g. \"Arisan Bulanan RT 04\", \"Arisan PKK\"\n  nominalIuran      Int // Nominal per putaran, misal Rp 50.000\n  periodeTipe       String   @default(\"bulanan\") // \"mingguan\", \"bulanan\", \"dua_mingguan\"\n  hariJawa          String? // e.g. \"Malam Minggu Pon\", \"Malam Jumat Kliwon\", \"Minggu Pahing\"\n  waktuKocok        String? // e.g. \"19:30\"\n  lokasiKocok       String? // e.g. \"Balai RT\" / \"Rumah Pemenang Sebelumnya\"\n  autoSinkronAgenda Boolean  @default(true)\n  tanggalMulai      DateTime @default(now())\n  status            String   @default(\"aktif\") // \"aktif\", \"selesai\"\n  keterangan        String?\n\n  komunitasId String?\n  komunitas   Komunitas? @relation(fields: [komunitasId], references: [id], onDelete: Cascade)\n  createdAt   DateTime   @default(now())\n  updatedAt   DateTime   @updatedAt\n\n  peserta PesertaArisan[]\n  putaran PutaranArisan[]\n}\n\nmodel PesertaArisan {\n  id         String         @id @default(uuid())\n  kelompokId String\n  kelompok   KelompokArisan @relation(fields: [kelompokId], references: [id], onDelete: Cascade)\n\n  anggotaId String?\n  anggota   Anggota? @relation(fields: [anggotaId], references: [id], onDelete: SetNull)\n\n  namaPeserta String // Nama warga / custom slot\n  nomorSlot   Int     @default(1)\n  noHp        String?\n\n  sudahMenang   Boolean   @default(false)\n  tanggalMenang DateTime?\n\n  pemenangPutaran PutaranArisan[]         @relation(\"PemenangPutaran\")\n  pembayaran      PembayaranIuranArisan[]\n  createdAt       DateTime                @default(now())\n}\n\nmodel PutaranArisan {\n  id         String         @id @default(uuid())\n  kelompokId String\n  kelompok   KelompokArisan @relation(fields: [kelompokId], references: [id], onDelete: Cascade)\n\n  putaranKe    Int // 1, 2, 3 ...\n  tanggalKocok DateTime @default(now())\n  hariJawa     String? // e.g. \"Malam Minggu Pon\"\n\n  agendaId String?\n  agenda   Agenda? @relation(fields: [agendaId], references: [id], onDelete: SetNull)\n\n  totalTarget       Int    @default(0) // Hak total pemenang (totalPeserta * nominalIuran)\n  totalTerkumpul    Int    @default(0) // Iuran masuk dari yang sudah bayar\n  nominalDiserahkan Int    @default(0) // Uang yang diserahkan ke pemenang\n  nominalKurang     Int    @default(0) // Sisa yang belum diserahkan\n  statusTalangan    String @default(\"tidak_ditalangi\") // \"tidak_ditalangi\" | \"ditalangi_kas\"\n  nominalTalangan   Int    @default(0)\n\n  pemenangId      String?\n  pemenang        PesertaArisan? @relation(\"PemenangPutaran\", fields: [pemenangId], references: [id], onDelete: SetNull)\n  namaPemenang    String?\n  nominalDiterima Int            @default(0)\n\n  status      String  @default(\"terlaksana\")\n  catatan     String?\n  dicatatOleh String  @default(\"Admin RT\")\n\n  pembayaran PembayaranIuranArisan[]\n  createdAt  DateTime                @default(now())\n}\n\nmodel PembayaranIuranArisan {\n  id        String        @id @default(uuid())\n  putaranId String\n  putaran   PutaranArisan @relation(fields: [putaranId], references: [id], onDelete: Cascade)\n\n  pesertaId String\n  peserta   PesertaArisan @relation(fields: [pesertaId], references: [id], onDelete: Cascade)\n\n  statusKehadiran String    @default(\"hadir\") // \"hadir\" | \"izin\" | \"tidak_hadir\"\n  statusBayar     Boolean   @default(false)\n  tanggalBayar    DateTime?\n  nominal         Int       @default(0)\n  metode          String    @default(\"tunai\") // \"tunai\" | \"transfer\"\n  catatan         String?\n}\n\n// ==========================================\n// Platform CMS Content Store (Terisolasi dari RT)\n// ==========================================\nmodel PlatformCms {\n  id        String   @id @default(\"global\")\n  content   String   @db.Text\n  updatedAt DateTime @updatedAt\n  updatedBy String?\n}\n\n// ==========================================\n// Modul Musyawarah & Voting Warga\n// ==========================================\n\nmodel Voting {\n  id        String @id @default(uuid())\n  judul     String // Misal: \"Pengadaan Palang Pintu Otomatis & CCTV RT\"\n  deskripsi String @db.Text // Latar belakang & penjelasan\n  kategori  String @default(\"umum\") // \"pembangunan\", \"keuangan\", \"kegiatan\", \"pemilihan_ketua\", \"kebijakan\"\n\n  // Konfigurasi Hak Suara & Kerahasiaan\n  tipeHakSuara    String @default(\"per_kk\") // \"per_kk\" (1 Suara/Rumah) | \"per_warga\" (1 Suara/Warga)\n  tipeKerahasiaan String @default(\"anonim\") // \"anonim\" | \"terbuka\"\n  status          String @default(\"aktif\") // \"draft\" | \"aktif\" | \"selesai\" | \"dibatalkan\"\n\n  // Kuorum & Waktu\n  kuorumPersen   Int      @default(50) // Persentase minimal partisipasi agar sah (misal 50%)\n  tanggalMulai   DateTime @default(now())\n  tanggalSelesai DateTime // Batas akhir pemungutan suara\n\n  // Konteks Keuangan & Lampiran (Informatif)\n  estimasiBiaya Int?    @default(0) // Estimasi beban biaya kas bila ada\n  lampiranUrl   String? // Foto denah / dokumen proposal\n\n  dibuatOleh String   @default(\"Pengurus RT\")\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  komunitasId String?\n  komunitas   Komunitas? @relation(fields: [komunitasId], references: [id], onDelete: Cascade)\n\n  opsi     VotingOpsi[]\n  suara    VotingSuara[]\n  komentar VotingKomentar[]\n\n  @@index([komunitasId, status])\n}\n\nmodel VotingOpsi {\n  id       String @id @default(uuid())\n  votingId String\n  voting   Voting @relation(fields: [votingId], references: [id], onDelete: Cascade)\n\n  urutan         Int     @default(1)\n  judulOpsi      String // Misal: \"Opsi 1: Palang Otomatis RFID (Rp 4.200.000)\"\n  deskripsiOpsi  String? @db.Text\n  gambarUrl      String? // Foto kandidat / foto sampel\n  perkiraanBiaya Int?    @default(0)\n\n  suara VotingSuara[]\n\n  @@index([votingId])\n}\n\nmodel VotingSuara {\n  id       String @id @default(uuid())\n  votingId String\n  voting   Voting @relation(fields: [votingId], references: [id], onDelete: Cascade)\n\n  opsiId String\n  opsi   VotingOpsi @relation(fields: [opsiId], references: [id], onDelete: Cascade)\n\n  // Identitas Pemilih untuk Validasi & Audit Kuorum\n  anggotaId     String?\n  anggota       Anggota? @relation(fields: [anggotaId], references: [id], onDelete: SetNull)\n  noRumah       String? // Kunci validasi 1 KK 1 Suara\n  namaPemilih   String // Disimpan untuk verifikasi kuorum\n  alasanMemilih String? // Aspirasi opsional dari pemilih\n\n  // Metadata Audit\n  dicatatOleh String? // \"Mandiri\" atau nama pengurus jika dibantu input\n  waktuVote   DateTime @default(now())\n\n  komunitasId String?\n\n  @@index([votingId, noRumah])\n  @@index([votingId, anggotaId])\n  @@index([votingId, opsiId])\n}\n\nmodel VotingKomentar {\n  id       String @id @default(uuid())\n  votingId String\n  voting   Voting @relation(fields: [votingId], references: [id], onDelete: Cascade)\n\n  namaPengirim String\n  rolePengirim String?  @default(\"Warga\")\n  pesan        String   @db.Text\n  createdAt    DateTime @default(now())\n\n  @@index([votingId])\n}\n",
